from abc import ABC, abstractmethod

# Define the abstract class SortAlgorithm
class SortAlgorithm(ABC):
    @abstractmethod
    def sort(self, arr):
        pass

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, a, b):
        pass


# Implement the BubbleSort algorithm
class BubbleSort(SortAlgorithm):
    def sort(self, arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]) > 0:
                    self.swap(arr, j, j + 1)
        return arr


# Implement the SelectionSort algorithm
class SelectionSort(SortAlgorithm):
    def sort(self, arr):
        for i in range(len(arr)):
            min_idx = i
            for j in range(i + 1, len(arr)):
                if self.compare(arr[min_idx], arr[j]) < 0:
                    min_idx = j
            self.swap(arr, i, min_idx)
        return arr


